        m=re.search(r'Not repaired[^:]*:(.*)',l)
        if m and task:
            body=m.group(1)
            items=re.split(r'\((\d+)\)\s',body)
            # items: [pre, n, text, n, text...]
            for j in range(1,len(items)-1,2):
                n=items[j]; txt=items[j+1]
