import json,glob,re,os
out=[]
for f in sorted(glob.glob('transcripts/harness_82388ac1/subagents/*.jsonl')):
    txts=[]
    first=None
    for l in open(f):
        try: o=json.loads(l)
        except: continue
        s=json.dumps(o)
        if first is None and '"user"' in s[:400]: first=s[:0]
        if 'adversarial-findings' in s: txts.append(s)
    if not txts: continue
    s=txts[-1]
    # unescape by loading nested strings
    def strings(o):
        if isinstance(o,str): yield o
        elif isinstance(o,dict):
            for v in o.values(): yield from strings(v)
        elif isinstance(o,list):
            for v in o: yield from strings(v)
    best=None
    for st in strings(json.loads(s)):
        m=re.search(r'```json adversarial-findings\s*(\[.*?\])\s*```',st,re.S)
        if m:
            try: best=json.loads(m.group(1))
            except Exception as e: best=('ERR',str(e))
    if isinstance(best,list):
        hi=[x for x in best if x.get('verdict')=='SUSTAINED' and x.get('severity') in('CRITICAL','HIGH')]
        print('##',os.path.basename(f),len(best),'findings;',len(hi),'CRIT/HIGH')
        for x in hi: print('   ',x['severity'],'|',x.get('subject_table'),x.get('subject_key'),'|',x['claim_attacked'][:230])
    else: print('##',os.path.basename(f),'no parse',best if best else '')
